<?php
require_once __DIR__.'/config/database.php';require_once __DIR__.'/config/helpers.php';require_login();
$role=$_SESSION['role'];$staff=in_array($role,['admin','petugas'],true);
if($staff){$rows=$pdo->query("SELECT r.*,u.name reporter FROM reports r LEFT JOIN users u ON u.id=r.user_id ORDER BY r.created_at DESC LIMIT 80")->fetchAll();}
else{$stmt=$pdo->prepare("SELECT * FROM reports WHERE user_id=:uid ORDER BY created_at DESC");$stmt->execute(['uid'=>$_SESSION['user_id']]);$rows=$stmt->fetchAll();}
$pageTitle='Dashboard';$basePath='';require __DIR__.'/includes/header.php';?>
<section class="page-banner"><div class="container"><span class="eyebrow">RUANG KOLABORASI</span><h1>Halo, <?=e($_SESSION['user_name'])?>.</h1><p><?= $staff?'Kelola laporan dan bantu tindak lanjut masalah lingkungan.':'Pantau perkembangan laporan yang telah kamu kirim.'?></p></div></section>
<section class="section"><div class="container"><div class="dashboard-top"><div><h2><?= $staff?'Semua Laporan':'Laporan Saya'?></h2><p><?=count($rows)?> laporan tercatat</p></div><div class="dash-actions"><a class="btn btn-outline" href="logout.php">Keluar</a><?php if(!$staff):?><a class="btn btn-primary" href="buat-laporan.php">+ Buat Laporan</a><?php endif;?></div></div>
<div class="report-list"><?php foreach($rows as $r):?><article class="report-row"><div class="report-row-main"><div class="report-top"><span class="status <?=status_class($r['status'])?>"><?=e($r['status'])?></span><small><?=date('d M Y',strtotime($r['created_at']))?></small></div><h3><?=e($r['title'])?></h3><p><?=e(excerpt($r['description'],150))?></p><div class="report-meta">⌖ <?=e($r['area'])?> · <?=e($r['waste_type'])?></div>
<?php if($staff):?><form class="status-form" method="post" action="update-status.php"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><select name="status"><?php foreach(['Menunggu','Diverifikasi','Ditangani','Selesai','Ditolak'] as $s):?><option <?=$r['status']===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select><input name="note" placeholder="Catatan tindak lanjut (opsional)" value="<?=e($r['staff_note']??'')?>"><button class="btn btn-small">Perbarui</button></form><?php elseif(!empty($r['staff_note'])):?><div class="staff-note"><b>Catatan petugas:</b> <?=e($r['staff_note'])?></div><?php endif;?></div></article><?php endforeach;?><?php if(!$rows):?><div class="empty">Belum ada laporan. Mulai berkontribusi dengan membuat laporan pertamamu.</div><?php endif;?></div></div></section>
<?php require __DIR__.'/includes/footer.php';?>
